   const manager = new CodexAppServerManager();
   const context = {
     session: {
@@ -59,12 +59,12 @@ function fixture() {
     turnId: "active-turn",
     serverName: "synara",
     mode: "form",
-    message: 'Allow the synara MCP server to run tool "a2a_raise"?',
+    message: `Allow the synara MCP server to run tool "${toolName}"?`,
     requestedSchema: { type: "object", properties: {} },
     _meta: {
       codex_approval_kind: "mcp_tool_call",
       persist: ["session"],
